INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('marchie-borja', 'Marchie Teodoro Borja', 'Principal Architect & Founder', 'RLA License No. 0054827', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=600&auto=format&fit=crop', 'Licensed Architect, UAP Makati Chapter Member, and Lecturer. Specialist in interdisciplinary design studies.', 'Marchie Teodoro Borja is a registered, licensed, and recognized professional Filipino architect by the Professional Regulation Commission (PRC) - Board of Architecture. He is an active member in good standing with the Integrated and Accredited Professional Organization of Architects (IAPOA) under the United Architects of the Philippines (UAP) Makati Chapter.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('jhoanna-ramos', 'Jhoanna Marie V. Ramos', 'HR & Finance Director', 'Corporate Treasurer & Partner', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=600&auto=format&fit=crop', 'Co-Founding Partner supervising Human Resources, organizational alignment, and fiscal administration.', 'Jhoanna Marie V. Ramos acts as the foundational administrative anchor of ATBP Collaborative. As the HR & Finance Director and Corporate Treasurer, she oversees the studio''s operational workflows, contract negotiations, progressive budget pipelines, and administrative transparency.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('adrian-mores', 'Adrian Ta-ay Mores', 'Technical Director & Partner', 'RLA License No. 0045492', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?q=80&w=600&auto=format&fit=crop', 'Licensed Architect and Registered Master Plumber. Technical Director and Corporate Secretary ensuring execution precision.', 'Adrian Ta-ay Mores is a multi-licensed professional specializing in complex building systems, structural coordination, and code compliance. Serving as Technical Director and Corporate Secretary of ATBP Collaborative, he bridges the gap between conceptual design and high-precision execution.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('nikka-oliveros', 'Nikka Jane Oliveros', 'Associate Architect', 'RLA License No. 0055109', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?q=80&w=600&auto=format&fit=crop', 'Associate Architect delivering layout blueprints, design studies, and construction document sets.', 'Nikka Jane Oliveros is an exceptionally detail-oriented professional architect focusing on space planning, material schedules, and precise construction documentation. As Associate Architect at ATBP Collaborative, she drives the drafting pipeline from initial schematic sketches to permit-ready contract document sets.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('mark-ramos', 'Mark Joseph Ramos', 'Senior BIM Specialist', 'Associate Partner', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=80&w=600&auto=format&fit=crop', 'Experienced BIM Specialist and Lead Architectural Draftsman, optimizing Revit/BIM standards.', 'Mark Joseph Ramos is an expert in Building Information Modeling (BIM) and digital architecture workflows. With over eight years of experience, he leads the digital drafting division at ATBP Collaborative, ensuring precise coordination across structural, mechanical, and architectural systems.', '"designers"'::text[], '[{"title":"Bachelor of Science in Architecture","description":"Graduated with an emphasis on digital architectural technologies and construction documentation methodologies."},{"title":"Certified Autodesk Revit Professional","description":"Industry-certified modeler managing complex multi-trade clash-detection, family creation, and parametric workflows."},{"title":"Digital Production Quality Controller","description":"Oversees digital drafting accuracy, model integrity standards, and structural synchronization across all design packages."}]'::jsonb, FALSE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, role = EXCLUDED.role, license = EXCLUDED.license, image = EXCLUDED.image, bio = EXCLUDED.bio, full_bio = EXCLUDED.full_bio, categories = EXCLUDED.categories, affiliations = EXCLUDED.affiliations, is_draft = EXCLUDED.is_draft, updated_at = NOW();
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('maria-santos', 'Maria Clara Santos', 'Senior Interior Designer', 'LID License No. 0008431', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?q=80&w=600&auto=format&fit=crop', 'Registered Interior Designer specializing in bespoke high-end residential fit-outs and materials curation.', 'Maria Clara Santos is a registered and licensed interior designer in the Philippines. She heads the space curation and interior materials department, working closely with the design team to blend local craft with contemporary minimalist spatial layouts.', '"designers"'::text[], '[{"title":"BS Interior Design, University of the Philippines","description":"Graduated with honors, focusing on ergonomic interior planning, spatial psychology, and bespoke fixture design."},{"title":"Active Member, Philippine Institute of Interior Designers (PIID)","description":"Participates in national interior design symposia, sustainable material councils, and artisanal craft collaborations."},{"title":"Acoustic Design & Lighting Certification","description":"Certified specialist in ambient architectural lighting layouts and interior acoustic performance optimization."}]'::jsonb, FALSE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, role = EXCLUDED.role, license = EXCLUDED.license, image = EXCLUDED.image, bio = EXCLUDED.bio, full_bio = EXCLUDED.full_bio, categories = EXCLUDED.categories, affiliations = EXCLUDED.affiliations, is_draft = EXCLUDED.is_draft, updated_at = NOW();
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('christian-alipio', 'Christian Alipio', 'Construction Project Manager', 'RCE License No. 0098412', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?q=80&w=600&auto=format&fit=crop', 'Registered Civil Engineer managing site execution, construction scheduling, and compliance.', 'Christian Alipio is a licensed civil engineer specializing in turnkey project management and site implementation. He directs on-site operations for ATBP Collaborative, coordinating subcontractors and ensuring structural integrity, material standards, and workplace safety.', '"managers","builders"'::text[], '[{"title":"BS Civil Engineering, Mapúa University","description":"Earned a degree in Civil Engineering with concentration in structural analysis and reinforced concrete design."},{"title":"Professional Project Management Specialist","description":"Coordinates turnkey site management, subcontractor work sequencing, and critical-path milestone tracking."},{"title":"OSHA Workplace Safety Certified","description":"Enforces occupational health, jobsite safety regulations, and risk-mitigation protocols across active build sites."}]'::jsonb, FALSE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, role = EXCLUDED.role, license = EXCLUDED.license, image = EXCLUDED.image, bio = EXCLUDED.bio, full_bio = EXCLUDED.full_bio, categories = EXCLUDED.categories, affiliations = EXCLUDED.affiliations, is_draft = EXCLUDED.is_draft, updated_at = NOW();
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('hannah-villanueva', 'Hannah Zarsaga Villanueva', 'Client Relations & Operations Manager', 'Operations & Administrative Lead', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?q=80&w=600&auto=format&fit=crop', 'Manages client onboarding, contract timelines, and day-to-day studio operations across active projects.', 'Hannah Zarsaga Villanueva oversees the client-facing side of ATBP Collaborative, from first-consultation scheduling through contract signing and progress reporting. She keeps every active engagement moving on a clear timeline, translating design and construction milestones into plain updates clients can act on.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('ernest-bambico', 'Ernest Bataller Bambico', 'Project Architect & Construction Detailer', 'RLA License No. 0061204', 'https://images.unsplash.com/photo-1519345182560-3f2917c472ef?q=80&w=600&auto=format&fit=crop', 'Licensed Architect bridging design intent and buildability through detailed construction drawings and site checks.', 'Ernest Bataller Bambico is a licensed architect who works at the intersection of design and construction, developing the detailed drawings that keep concept designs buildable and code-compliant. He regularly visits active sites to verify that executed work matches design intent before sign-off.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('john-dave-aquino', 'John Dave Lacaba Aquino', 'Design-Build Specialist', 'RLA License No. 0058873', 'https://images.unsplash.com/photo-1607990283143-e81e7a2c9349?q=80&w=600&auto=format&fit=crop', 'Licensed Architect handling both schematic design and hands-on fabrication oversight for modular builds.', 'John Dave Lacaba Aquino is a licensed architect specializing in design-build delivery, where the same team that designs a space also oversees its fabrication and assembly. He develops schematic concepts through to shop-ready drawings, then stays involved through fabrication and installation.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('rafael-bautista', 'Rafael Miguel Bautista', 'Site Engineer', 'RCE License No. 0102337', 'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?q=80&w=600&auto=format&fit=crop', 'Registered Civil Engineer overseeing structural execution, formworks, and day-to-day site safety.', 'Rafael Miguel Bautista is a licensed civil engineer responsible for structural execution on active sites, from formwork inspection to concrete pour quality control. He works alongside construction managers to keep crews on schedule without compromising structural standards.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('patricia-yumang', 'Patricia Anne Yumang', 'Junior Architect', 'RLA License No. 0064910', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=600&auto=format&fit=crop', 'Licensed Architect supporting schematic design studies, material research, and presentation drawings.', 'Patricia Anne Yumang supports the design team across early-stage schematic studies, material research, and client presentation drawings. She has a particular interest in passive tropical design strategies and spends much of her research time studying local material availability and craft techniques.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('andrea-fernandez', 'Andrea Nicole Fernandez', 'Design Director', 'RLA License No. 0067452', 'https://images.unsplash.com/photo-1544723795-3fb6469f5b39?q=80&w=600&auto=format&fit=crop', 'Licensed Architect steering design direction and creative quality control across the studio''s active projects.', 'Andrea Nicole Fernandez sets and safeguards the design language across every active engagement at ATBP Collaborative, reviewing concept development at each major milestone before it reaches the client. She works directly with project architects to keep material choices, spatial logic, and detailing consistent with the studio''s design philosophy.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('miguel-torres', 'Miguel Angelo Torres', 'Construction Supervisor', 'Certified Construction Supervisor', 'https://images.unsplash.com/photo-1552058544-f2b08422138a?q=80&w=600&auto=format&fit=crop', 'Oversees day-to-day crew work, materials handling, and jobsite safety across active construction sites.', 'Miguel Angelo Torres runs the daily rhythm of ATBP Collaborative''s active construction sites, coordinating crew schedules, materials deliveries, and safety briefings before work begins each day. He is the first point of contact for on-site issues, escalating design conflicts to the project architects while keeping the build moving.
INSERT INTO public.members (id, name, role, license, image, bio, full_bio, categories, affiliations, is_draft) VALUES ('kristelle-del-rosario', 'Kristelle Anne Del Rosario', 'Quantity Surveyor & Cost Estimator', 'Registered Quantity Surveyor', 'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?q=80&w=600&auto=format&fit=crop', 'Prepares cost estimates, material take-offs, and budget tracking across design and construction phases.', 'Kristelle Anne Del Rosario translates design drawings into detailed material take-offs and cost estimates, giving both the studio and its clients a clear picture of budget exposure before ground is broken. She tracks actual spend against estimate throughout construction, flagging variances early enough for the team to adjust.
INSERT INTO public.projects (id, title, category, main_category, subcategory, location, year, client_type, description, full_writeup, images, video, status, specs, is_draft) VALUES ('urban-living-1', 'Multi-Generational Project 1', 'Multi-Generational', 'Shelter', 'Multi-Generational', 'Metro Manila, Philippines', '2021', 'Mid-High-Income', 'A stunning Multi-Generational project showcasing modern architecture and sustainable design principles, deeply integrated into its surroundings.', 'This is a comprehensive full writeup for the Multi-Generational Project 1. It incorporates sustainable materials, passive cooling strategies, and a meticulous response to the tropical context. The spaces are fluid and interconnected, making the best use of natural light.', '"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80"'::text[], 'https://www.youtube.com/watch?v=aqz-KE-bpKQ', 'completed', '{"area":"140 sqm","scope":"comprehensive design","duration":"9 Months","materials":["Concrete","Wood","Steel","Glass"]}'::jsonb, FALSE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, main_category = EXCLUDED.main_category, subcategory = EXCLUDED.subcategory, location = EXCLUDED.location, year = EXCLUDED.year, client_type = EXCLUDED.client_type, description = EXCLUDED.description, full_writeup = EXCLUDED.full_writeup, images = EXCLUDED.images, video = EXCLUDED.video, status = EXCLUDED.status, specs = EXCLUDED.specs, is_draft = EXCLUDED.is_draft, updated_at = NOW();
