INSERT INTO public.projects (id, title, category, main_category, subcategory, location, year, client_type, description, full_writeup, images, video, status, specs, is_draft) VALUES ('tiny-living-3', 'Tiny Living Project 1', 'Tiny Living', 'Shelter', 'Tiny Living', 'Metro Manila, Philippines', '2023', 'Mid-High-Income', 'A stunning Tiny Living project showcasing modern architecture and sustainable design principles, deeply integrated into its surroundings.', 'This is a comprehensive full writeup for the Tiny Living Project 1. It incorporates sustainable materials, passive cooling strategies, and a meticulous response to the tropical context. The spaces are fluid and interconnected, making the best use of natural light.', '"https://images.unsplash.com/photo-1582268611958-ebfd161ef9cf?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600607686527-6fb886090705?auto=format&fit=crop&w=1200&q=80"'::text[], 'https://www.youtube.com/watch?v=aqz-KE-bpKQ', 'ongoing', '{"area":"142 sqm","scope":"comprehensive design","duration":"21 Months","materials":["Concrete","Wood","Steel","Glass"]}'::jsonb, FALSE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, main_category = EXCLUDED.main_category, subcategory = EXCLUDED.subcategory, location = EXCLUDED.location, year = EXCLUDED.year, client_type = EXCLUDED.client_type, description = EXCLUDED.description, full_writeup = EXCLUDED.full_writeup, images = EXCLUDED.images, video = EXCLUDED.video, status = EXCLUDED.