INSERT INTO public.site_settings (key, content, updated_at) VALUES ('contact_info', '{"address":"P4, B2, L1, N402 Lovebird Lane corner Eagle Drive, Countryside Village, Barangay Sun Valley, City of Parañaque, National Capital Region, Philippines, Southeast Asia.","addressLines":["P4, B2, L1, N402 Lovebird Lane corner Eagle Drive, Countryside Village,","Barangay Sun Valley, City of Parañaque, National Capital Region,","Philippines, Southeast Asia"],"landline":"+632 8257-0968","mobile":"+63 917 165 4827","email":"enquire@atbpcollaborative.com","socials":{"facebook":{"label":"ATBP Collaborative","url":"https://www.facebook.com/atbp.collaborative/"},"threads":{"label":"@atbp.collaborative","url":"https://www.threads.com/@atbp.collaborative"},"instagram":{"label":"@atbp.collaborative","url":"https://www.instagram.com/atbp.collaborative"},"youtube":{"label":"@atbpcollaborative9514","url":"https://www.youtube.com/@atbpcollaborative9514"}}}'::jsonb, NOW()) ON CONFLICT (key) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();
INSERT INTO public.site_settings (key, content, updated_at) VALUES ('privacy_policy', '{"title":"Privacy Policy","subtitle":"ATBP Collaborative • Design-Build Practice","icon":"ShieldCheck","closeLabel":"Close & Accept","intro":{"title":"Effective Date: January 1, 2026","text":"This Privacy Policy outlines how ATBP Collaborative (under the Licensed Architectural Practice of Marchie Teodoro Borja, PRC Registration No. 0054827 / SEC OPC) collects, uses, protects, and handles your data in compliance with the Data Privacy Act of 2012 (<a href=\"https://www.officialgazette.gov.ph/2012/08/15/republic-act-no-10173/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">Republic Act No. 10173</a>) and professional guidelines governing design-build practices in the Philippines."},"sections":[{"icon":"FileText","title":"1. Information We Collect","text":"When you interact with ATBP Collaborative—whether through our Discovery Intake form, project proposal requests, site consultation inquiries, or digital portals—we collect relevant information necessary to deliver architectural and construction services:","list":["<strong>Personal Identification:</strong> Full name, company affiliation, contact numbers, email address, and billing parameters.","<strong>Project & Site Coordinates:</strong> Property location, land title details, lot dimensions, topographic data, zoning constraints, budget brackets, and design preferences.","<strong>Technical & Media Assets:</strong> Architectural sketches, CAD/BIM models, reference images, site photos, and technical documentation uploaded during consultations.","<strong>Digital Usage Data:</strong> Anonymized browser metadata, device identifiers, and page interaction statistics collected via cookies to optimize website performance."]},{"icon":"UserCheck","title":"2. How We Use Your Information","text":"All collected data is processed strictly for legitimate architectural and design-build operations:","list":["Formulating custom design proposals, project scopes, cost estimations, and architectural contracts.","Managing Discovery Sessions, site inspections, design reviews, and construction phase coordination.","Facilitating local government unit (LGU) building permit applications, zoning compliance, and regulatory submissions under <a href=\"https://lawphil.net/statutes/repacts/ra2004/ra_9266_2004.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">Republic Act No. 9266</a> (The Architecture Act of 2004).","Communicating project updates, milestone deliverables, and administrative invoices."]},{"icon":"Lock","title":"3. Data Security & Intellectual Property Safeguards","text":"We implement robust physical, technical, and organizational security measures to protect your personal and project information against unauthorized access, loss, or alteration:","list":["Confidential project files and client blueprints are stored on encrypted cloud servers with strict role-based access controls.","All architectural designs, structural calculations, and technical documentation produced by ATBP Collaborative remain protected under professional copyright and <a href=\"https://lawphil.net/statutes/repacts/ra2004/ra_9266_2004.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">RA 9266</a> laws.","We never sell, trade, or rent client personal or project data to external marketers or unauthorized third parties."]},{"icon":"Globe","title":"4. Third-Party Disclosures & Sub-Consultants","text":"To execute comprehensive design-build projects, we may share essential project specifications with authorized third parties strictly on a need-to-know basis:","list":["Licensed engineering sub-consultants (Structural, MEPFS, Sanitary, Geotechnical specialists).","Contracted construction crews, material suppliers, and specialized fabricators.","Government regulatory bodies (Building Officials, Fire Marshals, Subdivision Associations) for legal permit processing."]},{"icon":"Scale","title":"5. Your Rights & Retention","text":"Under the Philippine <a href=\"https://www.officialgazette.gov.ph/2012/08/15/republic-act-no-10173/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">Data Privacy Act of 2012</a>, you hold the right to:","list":["Request access to the personal data we hold about you.","Request correction or updates to inaccurate project details.","Withdraw consent or request erasure of non-statutory records (subject to mandatory legal retention periods for building plans)."]}],"items":["<div class=\"p-5 border mt-4 border-space-sparkle/20 bg-space-sparkle/5 dark:bg-white/5 text-mini\"><h4 class=\"font-sans font-bold text-caption uppercase tracking-wider mb-2\">Contact Our Privacy Officer</h4><p class=\"opacity-80 mb-2\">If you have questions, concerns, or requests regarding this Privacy Policy or your data, please contact ATBP Collaborative:</p><div class=\"font-mono text-mini opacity-90 space-y-0.5\"><p>Email: <a href=\"mailto:enquire@atbpcollaborative.com\" class=\"underline hover:opacity-100\">enquire@atbpcollaborative.com</a></p><p>Practice Principal: Marchie Teodoro Borja, Architect (PRC No. 0054827)</p><p>Address: Metro Manila, Philippines</p></div></div>"]}'::jsonb, NOW()) ON CONFLICT (key) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();
INSERT INTO public.site_settings (key, content, updated_at) VALUES ('legal_notices', '{"title":"Legal & Regulatory Notices","subtitle":"ATBP Collaborative • Licensed Architectural Practice","icon":"Scale","intro":{"title":"Professional Practice Disclaimer","text":"ATBP Collaborative operates under the licensed architectural practice of Architect Marchie Teodoro Borja. All professional services, contract drawings, technical specifications, and construction supervisions comply with <a href=\"https://lawphil.net/statutes/repacts/ra2004/ra_9266_2004.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">Republic Act No. 9266</a> and Philippine building regulations."},"sections":[{"icon":"Award","title":"1. Professional Registration & Accreditation","list":["<strong>Professional Regulation Code (<a href=\"https://lawphil.net/statutes/repacts/ra2004/ra_9266_2004.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">RA 9266</a>):</strong> Sec. 37 Architectural Practice Regulations.","<strong>PRC Registration:</strong> Architect License No. 0054827 | Board of Architecture (PRC-BOA) Registration No. 0054827.","<strong>PRC-BOMP Certification:</strong> Registration No. 0012169.","<strong>SEC Registry:</strong> Registered One-Person Corporation (OPC) 2026."]},{"icon":"FileText","title":"2. Architectural Ownership & Copyright","text":"Under Section 33 of <a href=\"https://lawphil.net/statutes/repacts/ra2004/ra_9266_2004.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"underline hover:text-space-sparkle transition-colors\">Republic Act No. 9266</a> (The Architecture Act of 2004), drawings, specifications, CAD/BIM models, render visuals, and contract documents prepared by ATBP Collaborative as instruments of service are the intellectual property and copyright of the Architect.<br/><br/><span class=\"opacity-85 text-mini\">Reproduction, modification, or re-use of design assets for other sites or projects without prior express written consent is strictly prohibited under Philippine copyright law.</span>"},{"icon":"Building2","title":"3. Honest & Transparent Construction Standard","text":"ATBP Collaborative upholds an absolute transparent billing model across all design-build projects. Detailed bill of quantities (BOQ), material specifications, labor breakdowns, and subcontractor pricing are disclosed openly to clients without hidden markups."}]}'::jsonb, NOW()) ON CONFLICT (key) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();
INSERT INTO public.site_settings (key, content, updated_at) VALUES ('studio_writeups', '{"tagline":"Designing with Values. Building with Culture. Managing with Integrity.","subSlogan":"A Philippine architectural and design-build practice dedicated to cultural truth, spatial poetry, and structural honesty.","philosophy":"ATBP Collaborative operates under the licensed architectural practice of Architect Marchie Teodoro Borja. We champion honest construction standards, non-hidden markups, and contextual architecture suited to the Philippine climate and socio-economic landscape.","cultureStatement":"From indigenous vernacular tectonics to contemporary tropical minimalism, our works celebrate local craftsmanship, passive cooling, and enduring craftsmanship."}'::jsonb, NOW()) ON CONFLICT (key) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();